-- All writes go through checked RPCs. No client table-write grants.
create extension if not exists pg_jsonschema with schema extensions;
create schema if not exists euzen_sync;
revoke all on schema euzen_sync from public, anon, authenticated;
create table euzen_sync.schemas(kind text primary key, definition json not null);
