create table euzen_sync.accounts(owner uuid primary key references auth.users(id) on delete cascade, generation bigint not null default 1 check(generation>0));
create table euzen_sync.entities(owner uuid not null references euzen_sync.accounts(owner) on delete cascade, kind text not null references euzen_sync.schemas(kind), id text not null check(length(id) between 1 and 100), revision bigint not null check(revision>0), payload jsonb, primary key(owner,kind,id),check(payload is null or octet_length(payload::text)<=2000000));
create table euzen_sync.receipts(owner uuid not null references euzen_sync.accounts(owner) on delete cascade, operation uuid not null, request jsonb not null, response jsonb not null, primary key(owner,operation));
alter table euzen_sync.accounts enable row level security;
alter table euzen_sync.entities enable row level security;
alter table euzen_sync.receipts enable row level security;
alter table euzen_sync.schemas enable row level security;
-- Private functions intentionally have definer privileges; ownership is checked inside.
create function public.euzen_sync_pull() returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); result jsonb;
begin
 if u is null then raise exception 'Authentication required' using errcode='42501'; end if;
 insert into euzen_sync.accounts(owner) values(u) on conflict do nothing;
 perform 1 from euzen_sync.accounts where owner=u for update;
 select jsonb_build_object('owner',u,'generation',a.generation,'entities',coalesce((select jsonb_agg(jsonb_build_object('kind',e.kind,'id',e.id,'revision',e.revision,'payload',e.payload) order by e.kind,e.id) from euzen_sync.entities e where e.owner=u),'[]'::jsonb)) into result from euzen_sync.accounts a where a.owner=u;
 return result;
end $$;
create function public.euzen_sync_push(op jsonb) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); g bigint; old euzen_sync.entities; receipt euzen_sync.receipts; result jsonb; k text:=op->>'kind'; eid text:=op->>'entityId'; p jsonb:=op->'payload'; ref text; definition json;
begin
 if u is null or (op->>'owner')::uuid is distinct from u then raise exception 'Owner mismatch' using errcode='42501'; end if;
 if op->>'id' is null or eid is null or length(eid) not between 1 and 100 or (op->>'generation')::bigint is null or (op->>'expectedRevision')::bigint is null or (op->>'expectedRevision')::bigint<0 or jsonb_typeof(op->'remove') is distinct from 'boolean' then raise exception 'Invalid operation'; end if;
 insert into euzen_sync.accounts(owner) values(u) on conflict do nothing;
 select generation into g from euzen_sync.accounts where owner=u for update;
 if g is distinct from (op->>'generation')::bigint then raise exception 'Stale generation'; end if;
 select * into receipt from euzen_sync.receipts where owner=u and operation=(op->>'id')::uuid;
 if found then
  if receipt.request<>op then raise exception 'Operation reused'; end if;
  return receipt.response;
 end if;
 select s.definition into definition from euzen_sync.schemas s where kind=k;
 if definition is null then raise exception 'Invalid entity kind'; end if;
 if (op->>'remove')::boolean then
  if p is distinct from 'null'::jsonb then raise exception 'Invalid tombstone'; end if;
  p:=null;
 else
  if p is null or not extensions.jsonb_matches_schema(definition,p) then raise exception 'Invalid payload'; end if;
  if k in ('exercise','workout','week','scheduled','session') and p->>'id' is distinct from eid then raise exception 'ID mismatch'; end if;
  if k='checkin' and p->>'date' is distinct from eid then raise exception 'Date mismatch'; end if;
  if k='settings' and eid<>'preferences' then raise exception 'Settings ID mismatch'; end if;
 end if;
 select * into old from euzen_sync.entities where owner=u and kind=k and id=eid;
 if coalesce(old.revision,0)<>(op->>'expectedRevision')::bigint then
  return jsonb_build_object('kind','conflict','revision',coalesce(old.revision,0),'server',old.payload);
 end if;
 if p is not null and k='workout' then
  for ref in select distinct x.value->>'exerciseId' from jsonb_array_elements(p->'blocks') b cross join lateral jsonb_array_elements(b->'exercises') x loop
   if not exists(select 1 from euzen_sync.entities where owner=u and kind='exercise' and id=ref and payload is not null) then raise exception 'Missing own exercise'; end if;
  end loop;
 end if;
 if p is not null and k='scheduled' and p->>'kind'='workout' and not exists(select 1 from euzen_sync.entities where owner=u and kind='workout' and id=p->>'templateId' and payload is not null) then raise exception 'Missing own workout'; end if;
 if p is null and k='exercise' and exists(select 1 from euzen_sync.entities e cross join lateral jsonb_array_elements(e.payload->'blocks') b cross join lateral jsonb_array_elements(b->'exercises') x where e.owner=u and e.kind='workout' and x.value->>'exerciseId'=eid) then raise exception 'Exercise still referenced'; end if;
 if p is null and k='workout' and exists(select 1 from euzen_sync.entities where owner=u and kind='scheduled' and payload->>'templateId'=eid) then raise exception 'Workout still referenced'; end if;
 if not exists(select 1 from euzen_sync.entities where owner=u and kind=k and id=eid) and (select count(*) from euzen_sync.entities where owner=u)>=50000 then raise exception 'Entity quota exceeded'; end if;
 insert into euzen_sync.entities values(u,k,eid,coalesce(old.revision,0)+1,p) on conflict(owner,kind,id) do update set revision=excluded.revision,payload=excluded.payload;
 result:=jsonb_build_object('kind','accepted','revision',coalesce(old.revision,0)+1);
 insert into euzen_sync.receipts values(u,(op->>'id')::uuid,op,result);
 return result;
end $$;
revoke all on function public.euzen_sync_pull() from public,anon;
revoke all on function public.euzen_sync_push(jsonb) from public,anon;
grant execute on function public.euzen_sync_pull(),public.euzen_sync_push(jsonb) to authenticated;
